import{_ as r,c as a,o as t,ag as s}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Subscription-list","description":"","frontmatter":{"title":"Subscription-list"},"headers":[],"relativePath":"general/subscription-list.md","filePath":"general/subscription-list.md","lastUpdated":null}'),o={name:"general/subscription-list.md"};function n(i,e,h,l,c,d){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="subscription-list" tabindex="-1">Subscription-list <a class="header-anchor" href="#subscription-list" aria-label="Permalink to &quot;Subscription-list&quot;">​</a></h1><h3 id="rss" tabindex="-1">RSS <a class="header-anchor" href="#rss" aria-label="Permalink to &quot;RSS&quot;">​</a></h3><p>Online Articles and Podcast can be accessed via <a href="https://rss.irregularchat.com/i/" target="_blank" rel="noreferrer">https://rss.irregularchat.com/i/</a></p><h2 id="video-channels" tabindex="-1">Video Channels <a class="header-anchor" href="#video-channels" aria-label="Permalink to &quot;Video Channels&quot;">​</a></h2><h3 id="cybersecurity-and-privacy" tabindex="-1">Cybersecurity and Privacy <a class="header-anchor" href="#cybersecurity-and-privacy" aria-label="Permalink to &quot;Cybersecurity and Privacy&quot;">​</a></h3><ul><li><a href="https://www.youtube.com/c/NetworkChuck" target="_blank" rel="noreferrer">Network Chuck</a></li></ul><p><a href="https://www.youtube.com/c/NetworkChuck" target="_blank" rel="noreferrer">https://www.youtube.com/c/NetworkChuck</a> ## Software Defined Radios - <a href="https://www.youtube.com/channel/UC9U2kaqhE716J2WNSTcOghg" target="_blank" rel="noreferrer">cemaxecuter</a> Youtube is dedicated to keeping up with DragonOS. ## Development - <a href="https://www.youtube.com/c/TraversyMedia" target="_blank" rel="noreferrer">Traversy Media</a> - <a href="https://www.youtube.com/c/AngularFirebase" target="_blank" rel="noreferrer">Fireship</a> - <a href="https://www.youtube.com/c/TheNetNinja" target="_blank" rel="noreferrer">The Net Ninja</a> - <a href="https://www.youtube.com/c/Freecodecamp" target="_blank" rel="noreferrer">freeCodeCamp.org</a> - <a href="https://www.youtube.com/c/programmingwithmosh" target="_blank" rel="noreferrer">Programming with Mosh</a> ## Home Lab (Self-Host) - <a href="https://www.youtube.com/c/TechnoTimLive" target="_blank" rel="noreferrer">Techno Tim</a> ## Influence - <a href="https://www.youtube.com/c/CharismaonCommand" target="_blank" rel="noreferrer">Charisma on Command</a> - <a href="https://www.youtube.com/c/ImprovementPill" target="_blank" rel="noreferrer">Improvement Pill</a></p><h2 id="podcasts" tabindex="-1">Podcasts <a class="header-anchor" href="#podcasts" aria-label="Permalink to &quot;Podcasts&quot;">​</a></h2><h3 id="ai-ml" tabindex="-1">AI / ML <a class="header-anchor" href="#ai-ml" aria-label="Permalink to &quot;AI / ML&quot;">​</a></h3><h3 id="this-day-in-ai-rss" tabindex="-1"><a href="https://www.thisdayinai.com/" target="_blank" rel="noreferrer">This Day in AI</a> - <a href="https://feeds.transistor.fm/this-day-in-ai" target="_blank" rel="noreferrer">rss</a> <a class="header-anchor" href="#this-day-in-ai-rss" aria-label="Permalink to &quot;[This Day in AI](https://www.thisdayinai.com/) - [rss](https://feeds.transistor.fm/this-day-in-ai)&quot;">​</a></h3><blockquote><p>hour long commentary on the influence and rise of AI in technology and society ## Cybersecurity and Privacy</p></blockquote><h3 id="firewalls-don-t-stop-dragons-rss-sundays" tabindex="-1"><a href="https://firewallsdontstopdragons.com/podcast/" target="_blank" rel="noreferrer">Firewalls Don’t Stop Dragons</a> - <a href="https://podcast.firewallsdontstopdragons.com/feed/podcast/" target="_blank" rel="noreferrer">rss</a> - Sundays <a class="header-anchor" href="#firewalls-don-t-stop-dragons-rss-sundays" aria-label="Permalink to &quot;[Firewalls Don’t Stop Dragons](https://firewallsdontstopdragons.com/podcast/) - [rss](https://podcast.firewallsdontstopdragons.com/feed/podcast/) - Sundays&quot;">​</a></h3><blockquote><p>The show is a mix of cybersecurity news and interviews of prominent people in the industry. ### <a href="https://inteltechniques.com/podcast.html" target="_blank" rel="noreferrer">Inteltechniques</a> - <a href="https://feeds.soundcloud.com/users/soundcloud:users:261098918/sounds.rss" target="_blank" rel="noreferrer">rss</a> This weekly podcast presents ideas to help you become digitally invisible, stay secure from cyber threats, and make you a better online investigator. ### <a href="https://darknetdiaries.com/" target="_blank" rel="noreferrer">Darknet Diaries</a> - <a href="https://feeds.megaphone.fm/darknetdiaries" target="_blank" rel="noreferrer">rss</a> This is a podcast about hackers, breaches, shadow government activity, hacktivism, cybercrime, and all the things that dwell on the hidden parts of the network. This is Darknet Diaries. ### <a href="https://talosintelligence.com/podcasts/shows/beers_with_talos" target="_blank" rel="noreferrer">Beers with Talos</a> - <a href="https://feeds.feedburner.com/BeersWithTalosPodcast" target="_blank" rel="noreferrer">rss</a> - Thursdays Listen to Talos security experts as they bring their hot takes on current security topics and Talos research to the table. Along the way, Mitch, Liz, Matt, and a rotating chair of special guests will talk about anything (and we mean anything) that’s on their minds, from the latest YouTube trends to Olympic curling etiquette. New episodes every other Thursday. ### <a href="https://thehackermind.com/" target="_blank" rel="noreferrer">The Hacker Mind</a> an original podcast from ForAllSecure. It’s the stories of the individuals behind the hacks you’ve read about. It’s about meeting some security challenges in software through advanced techniques such as fuzz testing. It’s a view of the hackers and their world that you may not have heard of before. ### <a href="http://podcast.wh1t3rabbit.net/" target="_blank" rel="noreferrer">Down the security rabbit hole</a> - <a href="http://podcast.wh1t3rabbit.net/rss" target="_blank" rel="noreferrer">rss</a></p></blockquote><h3 id="development" tabindex="-1">Development <a class="header-anchor" href="#development" aria-label="Permalink to &quot;Development&quot;">​</a></h3><ul><li><p><a href="https://softwareengineeringdaily.com/category/podcast/" target="_blank" rel="noreferrer">Software Engineering Daily</a> - <a href="https://feeds.feedburner.com/SoftwareEngineeringDaily" target="_blank" rel="noreferrer">rss</a> &gt; Software Engineering Daily is a podcast covering software development topics, including programming languages, frameworks, and cloud computing.</p></li><li><p><a href="https://www.codingblocks.net/" target="_blank" rel="noreferrer">Coding Blocks</a> - <a href="https://www.codingblocks.net/feed/podcast/" target="_blank" rel="noreferrer">rss</a> &gt; Coding Blocks is a podcast focusing on software development, covering design patterns, software architecture, and best practices.</p></li></ul><h3 id="home-lab-self-host" tabindex="-1">Home Lab (Self-Host) <a class="header-anchor" href="#home-lab-self-host" aria-label="Permalink to &quot;Home Lab (Self-Host)&quot;">​</a></h3><h3 id="selfhosted" tabindex="-1"><a href="https://selfhosted.show/" target="_blank" rel="noreferrer">Selfhosted</a> - [ <a class="header-anchor" href="#selfhosted" aria-label="Permalink to &quot;[Selfhosted](https://selfhosted.show/) - [&quot;">​</a></h3><h3 id="influence" tabindex="-1">Influence <a class="header-anchor" href="#influence" aria-label="Permalink to &quot;Influence&quot;">​</a></h3><h3 id="misc" tabindex="-1">Misc <a class="header-anchor" href="#misc" aria-label="Permalink to &quot;Misc&quot;">​</a></h3><h3 id="https-freakonomics-com-podcasts-freakonomics" tabindex="-1"><a href="/general/tech-rss.html">https://freakonomics.com/podcasts/ Freakonomics</a> <a class="header-anchor" href="#https-freakonomics-com-podcasts-freakonomics" aria-label="Permalink to &quot;[https://freakonomics.com/podcasts/ Freakonomics](/general/tech-rss)&quot;">​</a></h3><blockquote><p>Discover the hidden side of everything with host Stephen J. Dubner, co-author of the Freakonomics books. Each week, Freakonomics Radio tells you things you always thought you knew (but didn’t) and things you never thought you wanted to know (but do) — from the economics of sleep to how to become great at just about anything, plus the true stories of minimum wage, rent control, and the gender pay gap. Dubner speaks with Nobel laureates and provocateurs, intellectuals and entrepreneurs, and various other underachievers</p></blockquote><h3 id="military" tabindex="-1">Military <a class="header-anchor" href="#military" aria-label="Permalink to &quot;Military&quot;">​</a></h3><h3 id="irregular-warfare-podcast" tabindex="-1"><a href="https://mwi.usma.edu/category/podcasts/irregular-warfare-podcast/" target="_blank" rel="noreferrer">Irregular Warfare Podcast</a> <a class="header-anchor" href="#irregular-warfare-podcast" aria-label="Permalink to &quot;[Irregular Warfare Podcast](https://mwi.usma.edu/category/podcasts/irregular-warfare-podcast/)&quot;">​</a></h3><h3 id="ubran-warfare-project" tabindex="-1"><a href="https://mwi.usma.edu/urban-warfare-project/urban-warfare-project-podcast/" target="_blank" rel="noreferrer">Ubran Warfare Project</a> <a class="header-anchor" href="#ubran-warfare-project" aria-label="Permalink to &quot;[Ubran Warfare Project](https://mwi.usma.edu/urban-warfare-project/urban-warfare-project-podcast/)&quot;">​</a></h3><blockquote><p>We need to man, organize, train and equip the force for operations in urban areas, highly dense urban areas, and that’s a different construct. We’re not organized like that right now.</p></blockquote><h3 id="_1sfc-rss" tabindex="-1"><a href="https://1stspecialforcescommand.buzzsprout.com/" target="_blank" rel="noreferrer">1SFC</a> - <a href="https://feeds.buzzsprout.com/1389175.rss" target="_blank" rel="noreferrer">rss</a> <a class="header-anchor" href="#_1sfc-rss" aria-label="Permalink to &quot;[1SFC](https://1stspecialforcescommand.buzzsprout.com/) - [rss](https://feeds.buzzsprout.com/1389175.rss)&quot;">​</a></h3><blockquote><p>a podcast where we examine the role of the Nation’s Premier Partnership Force across the competition continuum - from cooperation to conflict, and everything in between. ### <a href="https://pineland-underground.simplecast.com/" target="_blank" rel="noreferrer">Pineland Undergrounad</a> - <a href="https://feeds.simplecast.com/uxbe4lSy" target="_blank" rel="noreferrer">rss</a> The official podcast of the U.S. Army John F. Kennedy Special Warfare Center and School at Fort Bragg, North Carolina. Green Berets, Major Bobby Tuttle and Sergeant Major Chuck Ritter, embark on a journey to provide the best podcast in the military with bi-monthly relentless awesomeness. Real. Bold. Un-restricted.</p></blockquote><h3 id="western-way-of-war-rss" tabindex="-1"><a href="https://westernwayofwar.libsyn.com/website" target="_blank" rel="noreferrer">Western Way of War</a> <a href="http://feeds.libsyn.com/277478/rss" target="_blank" rel="noreferrer">rss</a> <a class="header-anchor" href="#western-way-of-war-rss" aria-label="Permalink to &quot;[Western Way of War](https://westernwayofwar.libsyn.com/website) [rss](http://feeds.libsyn.com/277478/rss)&quot;">​</a></h3><blockquote><p>A collection of discussions with those in the Profession of Arms that tries to understand the issues around how to fight, and succeed, against adversaries in the 2020s. We pose the questions as whether a single Western Way of Warfare (how Western militaries fight) has been successful, whether it remains fit for task today, and how it might need to adapt in the future? It is complemented by the ‘Adversarial Studies’ project that looks at how adversaries fight.</p></blockquote><ul><li><p><a href="https://warontherocks.com/category/warcast/" target="_blank" rel="noreferrer">War on the Rocks</a> - <a href="https://warontherocks.com/feed/podcast/" target="_blank" rel="noreferrer">rss</a> &gt; War on the Rocks is a podcast that covers topics related to international security and military affairs, featuring interviews with experts and policymakers.</p></li><li><p><a href="https://www.dvidshub.net/podcast/series/1266/the-spear" target="_blank" rel="noreferrer">The Spear</a> - <a href="https://feeds.dvidshub.net/podcast/rss/The-Spear" target="_blank" rel="noreferrer">rss</a> &gt; The Spear is a podcast from the US Marine Corps that features stories from Marines and other service members about their experiences in the military.</p></li><li><p><a href="https://acys.podbean.com/" target="_blank" rel="noreferrer">The Dead Prussian Podcast</a> - <a href="https://feed.podbean.com/acys/feed.xml" target="_blank" rel="noreferrer">rss</a> &gt; The Dead Prussian Podcast is a show that explores the nature of warfare, featuring interviews with military historians, strategists, and practitioners.</p></li></ul>',30)])])}const p=r(o,[["render",n]]);export{u as __pageData,p as default};
